module sequence_detector #(
    parameter IDLE = 5'b00001,
    parameter S1   = 5'b00010,
    parameter S2   = 5'b00100,
    parameter S3   = 5'b01000,
    parameter S4   = 5'b10000
) (
    input  clk,
    input  rst_n,
    input  data_in,
    output reg sequence_detected
);

reg [2:0] current_state, next_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) current_state <= IDLE; else current_state <= next_state;
end

always @(*) begin
    next_state = current_state;
    sequence_detected = 1'b0;

    case (current_state)
        IDLE: begin
            if (data_in == 1'b1)
                next_state = S1;
        end
        S1: begin
            if (data_in == 1'b0) next_state = S2; else next_state = IDLE;
        end
        S2: begin
            if (data_in == 1'b0) next_state = S3; else next_state = IDLE;
        end
        S3: begin
            if (data_in == 1'b1) next_state = S4; else next_state = IDLE;
        end
        S4: begin
            sequence_detected = 1'b1;
            next_state = IDLE;
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end

endmodule
